import{_ as a,C as d,o as i,c as n,j as t,a as s,E as r,a2 as c}from"./chunks/framework.M7K9TQZf.js";const P=JSON.parse('{"title":"Sign-up","description":"Signing up for Halyard, in three steps and one column. A form is where a component library either holds together or does not: every control here is a different…","frontmatter":{"title":"Sign-up","order":3,"aside":false},"headers":[],"relativePath":"examples/signup.md","filePath":"en/examples/signup.md","lastUpdated":1788614679000}'),l={name:"examples/signup.md"};function h(p,e,u,m,f,g){const o=d("Demo");return i(),n("div",null,[e[0]||(e[0]=t("h1",{id:"sign-up",tabindex:"-1"},[s("Sign-up "),t("a",{class:"header-anchor",href:"#sign-up","aria-label":'Permalink to "Sign-up"'},"​")],-1)),e[1]||(e[1]=t("p",{class:"plass-lede"},"Signing up for Halyard, in three steps and one column. A form is where a component library either holds together or does not: every control here is a different component, and they have to agree about height, about where a label sits, and about what an error looks like.",-1)),r(o,{src:"examples/signup",flutter:!1,"min-height":760}),e[2]||(e[2]=c('<p>The whole flow is one file: <code>docs/.vitepress/demos/examples/signup.tsx</code>. It is live, submit the first step empty and watch the errors arrive, then type any six digits to get past the code.</p><h2 id="composition" tabindex="-1">Composition <a class="header-anchor" href="#composition" aria-label="Permalink to &quot;Composition&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Block</th><th>Components</th><th>Worth noticing</th></tr></thead><tbody><tr><td>Progress</td><td><code>PlTimeline</code> <code>PlProgressLinear</code></td><td>A horizontal timeline rather than a bar alone, because the steps have names and a bar cannot say them</td></tr><tr><td>Account</td><td><code>PlTextField</code> <code>PlCheckbox</code> <code>PlDivider</code> <code>PlButton</code> <code>PlTextLink</code></td><td><code>error</code> on a field replaces its <code>description</code> and wires up <code>aria-describedby</code>; the checkbox takes one too</td></tr><tr><td>Social sign-in</td><td><code>PlButton</code></td><td><code>startIcon</code> and <code>fullWidth</code>, so the two buttons are one row on a wide canvas and a stack on a narrow one</td></tr><tr><td>Verify</td><td><code>PlOtpField</code> <code>PlPopover</code> <code>PlButton</code></td><td><code>groupSize={3}</code> splits six boxes into two groups, and paste fills all six at once</td></tr><tr><td>Profile</td><td><code>PlTextField</code> <code>PlCombobox</code> <code>PlDatePicker</code> <code>PlFilePicker</code> <code>PlRadioGroup</code> <code>PlSwitch</code></td><td>At the same <code>size</code> a field, a combobox and a date picker are the same height, so the two-column grid keeps its baselines</td></tr><tr><td>Done</td><td><code>PlAlert</code> <code>PlIcon</code> <code>PlButton</code></td><td>One <code>success</code> alert, and nothing else competing with it</td></tr><tr><td>Aside</td><td><code>PlCard</code> <code>PlList</code> <code>PlBlockquote</code> <code>PlAvatar</code> <code>PlTextLink</code></td><td>Reassurance, not navigation, so it is an <code>&lt;aside&gt;</code> and it disappears first</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Validation is ordinary React state. Nothing is marked wrong until the reader has tried to continue, which is why <code>tried</code> exists, a form that turns red while you are still typing in the first field is a form that is shouting.</li><li>The step is a number and the sections are plain conditionals. There is no wizard component in Plass and there does not need to be: a step is a piece of state and the rest is layout.</li><li><code>PlOtpField</code> is what the &quot;Verify&quot; button waits on. Six digits enable it; the field itself handles paste, backspace across boxes and the numeric keypad.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li>Two more whole screens: <a href="./dashboard">Admin dashboard</a> and <a href="./landing">Landing page</a>.</li><li>Per-component props and examples are under <a href="./../components/">Components</a>.</li></ul>',7))])}const x=a(l,[["render",h]]);export{P as __pageData,x as default};
